1	import { trace } from "@opentelemetry/api";
2	import { GameState, GameCard } from "../GameState.js";
3	import { GameId } from "../domain-types.js";
4	import {
5	  CardPlayedEvent,
6	  CardPlayedFaceDownEvent,
7	  ZoneHint,
8	  buildCardPlayedEvent,
9	  buildCardPlayedFaceDownEvent,
10	  buildCardReturnedEvent,
11	} from "../port-tabletop/types.js";
12	import { SpinePort, buildSeatJoinedPayload, defaultPlaymatImageUrl, playmatImageUrlFromPath, cardBackImageUrl, shufflerPublicUrl } from "./types.js";
13	import { colorsForPlaymat, DEFAULT_PLAYMAT_PATH } from "../table-look.js";
14	import { log } from "../log.js";
15	
16	export interface JoinSpineParams {
17	  gameId: GameId;
18	  tableName: string;
19	  playerName: string;
20	  deckName: string;
21	  sleeveColor?: string;
22	  playmatImagePath?: string;
23	  commanders?: readonly GameCard[];
24	}
25	
26	export interface SpineJoinOutcome {
27	  seatId?: string;
28	  spineTableId?: string;
29	  spineSeatNumber?: number;
30	  tableUrl?: string;
31	}
32	
33	/**
34	 * The one call that administers a seat: creates the table if needed, assigns a seat,
35	 * mints seat.taken + seat.joined on the Spine's own log, and has the Spine notify the
36	 * Tabletop. Best-effort — a down Spine must not block starting a game.
37	 */
38	export async function joinSpineBestEffort(spinePort: SpinePort | undefined, params: JoinSpineParams): Promise<SpineJoinOutcome> {
39	  if (!spinePort) return {};
40	  const { gameId, tableName, playerName, deckName, sleeveColor, playmatImagePath, commanders } = params;
41	  const playmatImageUrl = playmatImagePath ? playmatImageUrlFromPath(playmatImagePath) : defaultPlaymatImageUrl();
42	  const { primaryColor, secondaryColor } = colorsForPlaymat(playmatImagePath ?? DEFAULT_PLAYMAT_PATH, sleeveColor);
43	  const decoration = buildSeatJoinedPayload(
44	    deckName,
45	    `${shufflerPublicUrl()}/game/${gameId}`,
46	    playmatImageUrl,
47	    cardBackImageUrl(),
48	    sleeveColor,
49	    commanders,
50	    primaryColor,
51	    secondaryColor
52	  );
53	  try {
54	    const result = await spinePort.join({ gameId: String(gameId), name: tableName, playerName, ...decoration });
55	    return { seatId: result.seatId, spineTableId: result.tableId, spineSeatNumber: result.seatNumber, tableUrl: result.tableUrl };
56	  } catch (error) {
57	    trace.getActiveSpan()?.setAttributes({ "spine_join.failed": true, "table.name": tableName });
58	    log.warn("Spine join (table + seat) failed (best-effort; this game won't send to the Spine)", { "table.name": tableName }, error as Error);
59	    return {};
60	  }
61	}
62	
63	export async function sendCardPlayedToSpineBestEffort(
64	  spinePort: SpinePort | undefined,
65	  game: GameState,
66	  gameCard: GameCard,
67	  zoneHint: ZoneHint,
68	  sessionId?: string,
69	  faceDown = false
70	): Promise<void> {
71	  if (!spinePort || !game.spineTableId || !game.seatId || !gameCard.cardInstanceId) return;
72	  const tableId = game.spineTableId;
73	  try {
74	    const initiator = { seatId: game.seatId, playerName: game.playerName ?? "player", sessionId };
75	    const event: CardPlayedEvent | CardPlayedFaceDownEvent = faceDown
76	      ? buildCardPlayedFaceDownEvent(gameCard, gameCard.cardInstanceId, initiator, game.seatId, zoneHint, tableId)
77	      : buildCardPlayedEvent(gameCard, gameCard.cardInstanceId, initiator, game.seatId, zoneHint, tableId);
78	    await spinePort.sendEvent(tableId, event);
79	  } catch (error) {
80	    trace.getActiveSpan()?.setAttributes({ "spine_send.send_failed": true, "table.name": game.tableName ?? "" });
81	    log.warn("card.played send to Spine failed (best-effort; the Spine observes the log, it doesn't gate gameplay yet)", { "table.name": game.tableName ?? "" }, error as Error);
82	  }
83	}
84	
85	/**
86	 * Any transition out of the Shuffler's Table location (Return button, put-in-hand/top/bottom)
87	 * tells the Tabletop the card left, so it can poof the matching shape (ticket 07). Best-effort,
88	 * mirroring `sendCardPlayedToSpineBestEffort` — a down Spine must not block the Return action.
89	 */
90	export async function sendCardReturnedToSpineBestEffort(
91	  spinePort: SpinePort | undefined,
92	  game: GameState,
93	  gameCard: GameCard,
94	  sessionId?: string
95	): Promise<void> {
96	  if (!spinePort || !game.spineTableId || !game.seatId || !gameCard.cardInstanceId) return;
97	  const tableId = game.spineTableId;
98	  try {
99	    const initiator = { seatId: game.seatId, playerName: game.playerName ?? "player", sessionId };
100	    const event = buildCardReturnedEvent(gameCard, gameCard.cardInstanceId, initiator, game.seatId, tableId);
101	    await spinePort.sendEvent(tableId, event);
102	  } catch (error) {
103	    trace.getActiveSpan()?.setAttributes({ "spine_send.send_failed": true, "table.name": game.tableName ?? "" });
104	    log.warn("card.returned send to Spine failed (best-effort; the Spine observes the log, it doesn't gate gameplay yet)", { "table.name": game.tableName ?? "" }, error as Error);
105	  }
106	}
