{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/payloads/card.played.v1.json",
  "title": "card.played payload, schemaVersion 1",
  "description": "A game event from the Shuffler: it deterministically knows a card was played, so it says so. Card identity is the Scryfall ID (definition) plus a Shuffler-minted instance GUID (this particular Forest, for this game). Which seat played it lives on the envelope's initiator, not repeated here. Pre-Spine exception (tabletop-cards-come-and-go, ticket 05): frontImageUrl/backImageUrl/cardName are scaffolding render conveniences, promoted into this schema so ajv can validate the whole body now that zero real senders/receivers exist yet — the same in-place-edit exception envelope.v1 uses, not a new policy. Once a real consumer exists, reshaping this needs a v2.",
  "type": "object",
  "properties": {
    "card": {
      "type": "object",
      "properties": {
        "scryfallId": {
          "type": "string",
          "format": "uuid",
          "description": "Definition: the exact printing — oracle identity, all faces, all names, all images derivable."
        },
        "instanceId": {
          "type": "string",
          "format": "uuid",
          "description": "Instance: this particular physical-ish card, minted per game at game start. Opaque — distinct from the Shuffler's internal gameCardIndex (see the sibling `gameCardIndex` property below), which is a rank in a decklist array, not a stable per-card identity."
        }
      },
      "required": ["scryfallId", "instanceId"],
      "additionalProperties": true
    },
    "face": {
      "type": "string",
      "enum": ["front", "back"],
      "description": "Face is card state, not identity — but MDFCs are played as a chosen face, so it rides along."
    },
    "zoneHint": {
      "type": "string",
      "enum": ["stack", "battlefield", "graveyard"],
      "description": "Where the card is headed on the table. A hint — geography, not rules."
    },
    "frontImageUrl": {
      "type": "string",
      "format": "uri",
      "description": "Blessed scaffolding convenience: render without a Scryfall lookup."
    },
    "backImageUrl": {
      "type": ["string", "null"],
      "description": "Present (non-null) exactly when the card has a printed back face — null, never omitted, when it doesn't (two-faced-cards watch point 17)."
    },
    "cardName": {
      "type": "string",
      "minLength": 1,
      "description": "Blessed scaffolding convenience: display without a Scryfall lookup."
    },
    "owner": {
      "type": "string",
      "minLength": 1,
      "description": "The seatId of the player this card belongs to — under the Spine's join, that's the seat number (e.g. \"1\"-\"4\") as a string, not a GUID, so this stays a bare non-empty check. Grants no capability — any player can still move any card; it makes 'whose card is this' a fact the shape carries."
    },
    "isCommander": {
      "type": "boolean",
      "description": "Whether this card is one of its owner's commanders."
    },
    "gameCardIndex": {
      "type": "integer",
      "minimum": 0,
      "description": "The card's index in the Shuffler's initial decklist array (its alphabetical rank in that list) — not library order, which is shuffled. Used to be withheld here as a 'decodable secret' (let-gamecardindex-out, 2026-08-10 reversed that call): decklists are public on Archidekt anyway, the app doesn't police what a trust-based table can see, and the cost of the old guard was every future payload having to carry a model of what may cross. Optional: older senders may omit it, and no receiver is required to use it."
    }
  },
  "required": ["card", "face", "zoneHint", "frontImageUrl", "backImageUrl", "cardName", "owner", "isCommander"],
  "additionalProperties": true
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/payloads/card.returned.v1.json",
  "title": "card.returned payload, schemaVersion 1",
  "description": "A card left the table. Bidirectional: sent tabletop->shuffler (dragged off the playmat back into the Shuffler's game state — ticket 12's library portal) and, as of ticket 07, shuffler->tabletop (any transition out of the Shuffler's own Table location — the Return button, or a crafted put-in-hand/top/bottom — via `occurredIn: \"shuffler\"`), so a consumer must branch on `occurredIn` rather than assume a direction. The table isn't authoritative for a table card's face, so unlike card.played/card.discarded this event carries no `face` field (two-faced-cards watch point 19) — `face` is explicitly blacklisted (`\"face\": false`) rather than merely undeclared, since a sender copying card.played's shape by habit is the likely mistake to guard against; every other unknown property still passes through per the fleet's additionalProperties:true policy. Identity is scryfallId plus gameCardIndex (the Shuffler's own decklist rank), same as always — `card.instanceId` is an additional, optional identifier: the Shuffler always has it for a Table card (minted at newGame, already used by card.played) and now sends it too, so the Tabletop can poof the matching shape by its `instanceId` prop; a tabletop-initiated send may omit it.",
  "type": "object",
  "properties": {
    "card": {
      "type": "object",
      "properties": {
        "scryfallId": {
          "type": "string",
          "format": "uuid",
          "description": "Definition: the exact printing — oracle identity, all faces, all names, all images derivable."
        },
        "instanceId": {
          "type": "string",
          "description": "The Shuffler's per-play GUID for this physical card (same value card.played sends). Optional — present on a shuffler-initiated card.returned (ticket 07, so the Tabletop can find the shape to remove); may be absent on a tabletop-initiated one."
        }
      },
      "required": ["scryfallId"],
      "additionalProperties": true
    },
    "gameCardIndex": {
      "type": "integer",
      "minimum": 0,
      "description": "The card's index in the Shuffler's initial decklist array (its alphabetical rank in that list) — how the Shuffler looks this card back up in its own game state."
    },
    "seat": {
      "type": "string",
      "minLength": 1,
      "description": "The seatId of the player this card is returning to — a bare non-empty check, matching card.played.v1's `owner` field."
    },
    "fromZone": {
      "type": "string",
      "minLength": 1,
      "description": "Where on the table the card was returning from. A hint — geography, not rules."
    },
    "face": false
  },
  "required": ["card", "gameCardIndex", "seat"],
  "additionalProperties": true
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/envelope.v1.json",
  "title": "Spine Event Envelope",
  "description": "The fleet's published language: the envelope every event wears. Senders mint `id`; the Spine assigns `seq` and `acceptedAt` on append (they are absent at submission, present in the log). See contracts/README.md for the versioning policy.",
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "format": "uuid",
      "description": "Sender-minted GUID. Idempotency key: the Spine elides a retried duplicate."
    },
    "tableId": {
      "type": "string",
      "description": "Which table's log. Pre-Spine, the table name IS the id (unique among active tables) — no format constraint. Once the Spine mints a GUID at table creation, this field becomes that GUID and the name reverts to a lookup alias in the table.created payload."
    },
    "seq": {
      "type": "integer",
      "minimum": 1,
      "description": "Spine-assigned on append: authoritative order within the log. Senders must not set this."
    },
    "name": {
      "type": "string",
      "pattern": "^[a-z]+(\\.[a-z_-]+)+$",
      "description": "The event's kind, namespaced (e.g. card.played, card.played-face-down). Determines which payload schema applies."
    },
    "acceptedAt": {
      "type": "string",
      "format": "date-time",
      "description": "Spine-assigned on append: the Spine's clock, when the log accepted it. Senders must not set this."
    },
    "occurredAt": {
      "type": "string",
      "format": "date-time",
      "description": "Optional. The initiator app's clock, when physics preceded ingestion."
    },
    "initiator": {
      "type": "object",
      "description": "Who made this happen: a seated player, a named spectator, later the interpreter.",
      "properties": {
        "seatId": {
          "type": "string",
          "description": "Present when a seated player made this happen. Absent for a named spectator or other non-seated initiator."
        },
        "sessionId": {
          "type": "string",
          "description": "Per-context, per CONTEXT-MAP.md's \"Initiator\" table: the Shuffler mints one fresh per page load (gameId already anchors identity durably, so it's free to reset); the Tabletop mints one that must persist across a refresh (no durable anchor of its own) and, for an Anonymous Session, doubles as the client-generated pseudonym display label; the Spine only passes it through. Optional here; absent for an initiator that hasn't minted one."
        },
        "playerName": {
          "type": "string",
          "description": "Display only. Not unique, not an identity."
        }
      },
      "required": ["playerName"],
      "additionalProperties": false
    },
    "occurredIn": {
      "type": "string",
      "enum": ["shuffler", "tabletop", "spine"],
      "description": "Which application recorded/sent it. `interpreter` joins this enum later."
    },
    "origin": {
      "type": "string",
      "pattern": "^[a-z]+(\\.[a-zA-Z_]+)+$",
      "description": "One level more specific than `occurredIn`: which mechanism, within that app, minted this event (e.g. `shuffler.playCardSubmit`, `spine.seatTaken`, `tabletop.cardShapeHook`). An open, dot-namespaced string like `name` — not a closed enum, so a new call site anywhere in the fleet never needs a schema change first. Unlike `name` (fully lowercase), segments after the first app name may be camelCase, since a mechanism name (`tableLookupMiss`, `playCardSubmit`) reads naturally that way. Hard-coded literal, one per mint site."
    },
    "significance": {
      "type": "string",
      "enum": ["physical", "domain", "administrative"],
      "description": "What kind of fact this event states, independent of which app or mechanism produced it. `physical` — a card moved, hand sorting, a note/annotation on the table; raw motion/arrangement, meaning-free. `domain` — a real game-related fact (a card is drawn, played, or moved to a zone). `administrative` — table/seat bookkeeping (table.created, seat.taken, seat.joined), not gameplay itself."
    },
    "traceparent": {
      "type": "string",
      "pattern": "^00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}$",
      "description": "W3C trace context for this event, carried on the envelope itself rather than only a transport header — the outbound SSE stream has no header to ride, and a future batched `sendEvent` would otherwise lose per-event trace context. Optional: tracing is best-effort and must never be the reason an event is rejected. Observability only — traces expire (~60d); durable causality between events uses `id` references, never trace ids. The Spine's persisted log does not keep this field; it's attached fresh whenever an event is broadcast live."
    },
    "schemaVersion": {
      "type": "integer",
      "minimum": 1,
      "description": "Integer version of this `name`'s payload schema."
    },
    "payload": {
      "type": "object",
      "description": "The kind-specific body, validated against payloads/<name>.v<schemaVersion>.json."
    }
  },
  "required": [
    "id",
    "tableId",
    "name",
    "initiator",
    "occurredIn",
    "origin",
    "significance",
    "schemaVersion",
    "payload"
  ],
  "additionalProperties": true
}

